#!/usr/bin/env node
/**
 * Regenerate docs/recordings-stats.md and its infographic from parsed events.
 *
 * Reads page/src/misc/all-events.json (generated by tools/mdParser.js), computes
 * recording coverage, and writes docs/recordings-stats.md plus
 * docs/images/recordings-overall-events.png.
 *
 * Usage:
 *   node tools/mdParser.js
 *   node tools/generateRecordingsStats.js [options]
 *
 * Options:
 *   --date YYYY-MM-DD  snapshot date shown on the page (default: today)
 *   --no-image         skip the PNG infographic
 *
 * Requirements: the tools npm dependencies (sharp renders the infographic).
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { parseArgs } = require('node:util');

const ROOT = path.resolve(__dirname, '..');
const EVENTS = path.join(ROOT, 'page', 'src', 'misc', 'all-events.json');
const PAGE = path.join(ROOT, 'docs', 'recordings-stats.md');
const IMAGE = path.join(ROOT, 'docs', 'images', 'recordings-overall-events.png');

const PERIODS = ['2017-2020', '2021-2024', '2025', '2026', '2027-2028'];
const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

const BLUE = '#2864A5';
const NAVY = '#142B43';
const MID_BLUE = '#54708D';
const MINT = '#28A997';
const PALE_BLUE = '#EAF2FA';
const PALE_MINT = '#DDF4EE';
const PALE_ORANGE = '#FFF1DF';
const ORANGE = '#E99A3D';
const GRAY = '#DCE5EE';
const OFF_WHITE = '#F5F8FC';

const NUMBER_FORMATTER = new Intl.NumberFormat('en-US');

function formatNumber(value) {
  return NUMBER_FORMATTER.format(value);
}

function periodFor(year) {
  if (year <= 2020) {
    return '2017-2020';
  }
  if (year <= 2024) {
    return '2021-2024';
  }
  if (year <= 2026) {
    return String(year);
  }
  return '2027-2028';
}

function isPlaylist(url) {
  return String(url).includes('list=');
}

function isYouTube(url) {
  try {
    const host = new URL(url).hostname.toLowerCase();
    return (
      host === 'youtu.be' ||
      host === 'youtube.com' ||
      host.endsWith('.youtube.com')
    );
  } catch {
    return false;
  }
}

function percent(part, whole) {
  return whole ? `${((part / whole) * 100).toFixed(2)}%` : '0.00%';
}

function summarize(events) {
  const total = events.length;
  const recorded = events.filter(
    (event) => Array.isArray(event.recordings) && event.recordings.length > 0
  );
  const links = recorded.flatMap((event) => event.recordings);

  const byPeriod = {};
  for (const name of PERIODS) {
    byPeriod[name] = {
      events: 0,
      recorded: 0,
      links: 0,
      multi: 0,
      playlists: 0,
      videos: 0,
    };
  }

  for (const event of events) {
    const date = new Date(event.date[0]);
    const bucket = byPeriod[periodFor(date.getUTCFullYear())];
    bucket.events += 1;

    const entries = Array.isArray(event.recordings) ? event.recordings : [];
    if (!entries.length) {
      continue;
    }

    bucket.recorded += 1;
    bucket.links += entries.length;
    bucket.multi += entries.length > 1 ? 1 : 0;
    bucket.playlists += entries.filter((link) => isPlaylist(link.url)).length;
    bucket.videos += entries.filter((link) => !isPlaylist(link.url)).length;
  }

  const topCounter = new Map();
  for (const event of recorded) {
    const date = new Date(event.date[0]).toISOString().slice(0, 10);
    const linkCount = event.recordings.length;
    const key = JSON.stringify([event.name, date, linkCount]);
    const existing = topCounter.get(key);
    if (existing) {
      existing.total += 1;
    } else {
      topCounter.set(key, {
        name: event.name,
        date,
        count: linkCount,
        total: 1,
      });
    }
  }

  const top = [...topCounter.values()]
    .filter((row) => row.count >= 5)
    .sort((left, right) => {
      if (right.count !== left.count) {
        return right.count - left.count;
      }
      if (left.date !== right.date) {
        return left.date < right.date ? -1 : 1;
      }
      if (left.name === right.name) {
        return 0;
      }
      return left.name < right.name ? -1 : 1;
    })
    .map((row) => [row.name, row.date, row.count]);

  const playlists = links.filter((link) => isPlaylist(link.url)).length;
  return {
    total,
    recorded: recorded.length,
    links: links.length,
    multi: recorded.filter((event) => event.recordings.length > 1).length,
    playlists,
    videos: links.length - playlists,
    youtube: links.filter((link) => isYouTube(link.url)).length,
    by_period: byPeriod,
    top,
  };
}

function formatSnapshotDate(date) {
  return `${date.getDate()} ${MONTHS[date.getMonth()]} ${date.getFullYear()}`;
}

function isValidIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

function formatIsoSnapshotDate(isoDate) {
  if (!isValidIsoDate(isoDate)) {
    throw new Error('--date must use YYYY-MM-DD');
  }
  const [year, month, day] = isoDate.split('-').map(Number);
  return `${day} ${MONTHS[month - 1]} ${year}`;
}

function defaultSnapshotDate(now = new Date()) {
  return formatSnapshotDate(now);
}

function markdown(data, updated) {
  const rows = [];
  for (const name of PERIODS) {
    const bucket = data.by_period[name];
    const label = name.replace('-', '–');
    rows.push(
      `| ${label} | ${formatNumber(bucket.events)} | ${formatNumber(
        bucket.recorded
      )} | ${percent(bucket.recorded, bucket.events)} | ${formatNumber(
        bucket.links
      )} | ${formatNumber(bucket.multi)} | ${formatNumber(
        bucket.playlists
      )} | ${formatNumber(bucket.videos)} |`
    );
  }
  rows.push(
    `| **Total** | **${formatNumber(data.total)}** | **${formatNumber(
      data.recorded
    )}** | **${percent(data.recorded, data.total)}** | **${formatNumber(
      data.links
    )}** | **${formatNumber(data.multi)}** | **${formatNumber(
      data.playlists
    )}** | **${formatNumber(data.videos)}** |`
  );

  const topRows = data.top.map(
    ([name, date, count]) => `| ${name} | ${date} | ${count} |`
  );

  return `# Recording statistics

Last updated: ${updated}

This page summarizes recording coverage in the current repository data.
\`METADATA.csv\` is the source of record; \`tools/mdParser.js\` derives the event
data used by the website. Regenerate this page with
\`node tools/generateRecordingsStats.js\` after metadata changes.

An event counts as recorded when it has at least one public recording link.
Recording links include playlists, individual videos, archives, and organizer
pages. Links are counted per event entry, not as the number of videos contained
inside a playlist.

## Overall

| Metric | Value |
|---|---:|
| Event entries | ${formatNumber(data.total)} |
| Events with at least one recording | ${formatNumber(
    data.recorded
  )} (${percent(data.recorded, data.total)}) |
| Recording links | ${formatNumber(data.links)} |
| Events with multiple recordings | ${formatNumber(data.multi)} |
| Playlist links | ${formatNumber(data.playlists)} (${percent(
    data.playlists,
    data.links
  )}) |
| Video or other links | ${formatNumber(data.videos)} (${percent(
    data.videos,
    data.links
  )}) |
| YouTube links | ${formatNumber(data.youtube)} (${percent(
    data.youtube,
    data.links
  )}) |

![Conference events and recordings across all event years](images/recordings-overall-events.png)

## By event year

Events are grouped by the year of their start date.

| Event year | Event entries | With recordings | Coverage | Recording links | Multiple recordings | Playlists | Videos / other |
|---|---:|---:|---:|---:|---:|---:|---:|
${rows.join('\n')}

Future years are included in the event-entry totals but naturally have no
recordings yet. Coverage therefore describes the current metadata snapshot, not
a permanent property of an event year.

## Events with the most recording links

This table lists every event with five or more recording links. Ties are ordered
by date and event name.

| Event | Date | Recording links |
|---|---|---:|
${topRows.join('\n')}

## Link classification

Playlist links are identified by a \`list=\` URL parameter. Everything else,
including individual videos, channel pages, and archive pages, is classified as
video/other. This is a URL-based classification and does not count the
individual videos contained within a playlist.

Recording numbers are a snapshot of the public links currently recorded in
\`METADATA.csv\`. Missing links mean no public recording has been recorded in the
metadata, not that no recording exists. Re-run the metadata parser and this
script after data changes to keep this page and its infographic synchronized
with the generated event data.
`;
}

function escapeXml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;');
}

function textElement(x, y, value, size, color, options = {}) {
  const anchor = options.anchor || 'start';
  const weight = options.bold ? '700' : '400';
  const baseline = anchor === 'middle' ? 'central' : 'hanging';
  return `<text x="${x}" y="${y}" font-size="${size}" font-weight="${weight}" fill="${color}" text-anchor="${anchor}" dominant-baseline="${baseline}">${escapeXml(
    value
  )}</text>`;
}

function rectElement(x, y, width, height, radius, fill) {
  const safeWidth = Math.max(0, width);
  return `<rect x="${x}" y="${y}" width="${safeWidth}" height="${height}" rx="${radius}" fill="${fill}"/>`;
}

function buildSvg(data, updated) {
  const width = 1600;
  const height = 1500;
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`,
    '<style>text { font-family: Arial, "DejaVu Sans", sans-serif; }</style>',
    `<rect width="${width}" height="${height}" fill="${OFF_WHITE}"/>`,
  ];

  parts.push(
    textElement(72, 48, 'Conference events & recordings', 56, NAVY, {
      bold: true,
    }),
    textElement(
      74,
      125,
      `Overall statistics across all event years  /  ${updated}`,
      28,
      MID_BLUE
    ),
    rectElement(1280, 59, 248, 52, 25, PALE_BLUE),
    textElement(1404, 85, 'developers.events', 25, BLUE, {
      bold: true,
      anchor: 'middle',
    })
  );

  const cards = [
    [68, 200, 544, 418, formatNumber(data.total), 'event entries', BLUE, PALE_BLUE],
    [
      562,
      200,
      1038,
      418,
      formatNumber(data.recorded),
      'events with recordings',
      MINT,
      PALE_MINT,
    ],
    [
      1056,
      200,
      1532,
      418,
      formatNumber(data.links),
      'recording links',
      ORANGE,
      PALE_ORANGE,
    ],
  ];

  for (const [left, top, right, bottom, value, label, accent, background] of cards) {
    parts.push(
      rectElement(left, top, right - left, bottom - top, 24, background),
      textElement((left + right) / 2, top + 72, value, 64, accent, {
        bold: true,
        anchor: 'middle',
      }),
      textElement((left + right) / 2, top + 157, label, 25, NAVY, {
        bold: true,
        anchor: 'middle',
      })
    );
  }

  parts.push(
    textElement(
      800,
      468,
      `${percent(data.recorded, data.total)} of all event entries have at least one recording link`,
      28,
      NAVY,
      { bold: true, anchor: 'middle' }
    ),
    textElement(72, 550, 'Events compared by year', 40, NAVY, { bold: true }),
    rectElement(950, 558, 74, 24, 9, GRAY),
    textElement(1038, 553, 'All events', 24, MID_BLUE),
    rectElement(1190, 558, 74, 24, 9, BLUE),
    textElement(1278, 553, 'With recordings', 24, MID_BLUE)
  );

  const barLeft = 330;
  const barWidth = 1110;
  const rowStart = 650;
  const rowHeight = 137;
  const scale =
    Math.max(...PERIODS.map((name) => data.by_period[name].events), 0) || 1;

  PERIODS.forEach((name, index) => {
    const bucket = data.by_period[name];
    const y = rowStart + index * rowHeight;
    const totalWidth = Math.round((barWidth * bucket.events) / scale);
    const recordedWidth = Math.round((barWidth * bucket.recorded) / scale);
    const labelLeft = recordedWidth ? barLeft + recordedWidth + 18 : barLeft + 18;

    parts.push(
      textElement(74, y + 37, name.replace('-', '–'), 29, NAVY, { bold: true }),
      rectElement(barLeft, y, totalWidth, 42, 10, GRAY),
      textElement(
        barLeft + 18,
        y + 8,
        `${formatNumber(bucket.events)} events`,
        24,
        NAVY,
        { bold: true }
      )
    );

    if (recordedWidth) {
      parts.push(rectElement(barLeft, y + 58, recordedWidth, 42, 10, BLUE));
    } else {
      parts.push(
        `<line x1="${barLeft}" y1="${y + 79}" x2="${barLeft + 4}" y2="${
          y + 79
        }" stroke="${BLUE}" stroke-width="5"/>`
      );
    }

    let detail = `${formatNumber(bucket.links)} recording links`;
    if (name === '2027-2028') {
      detail += '  /  upcoming';
    }

    parts.push(
      textElement(
        labelLeft,
        y + 66,
        `${formatNumber(bucket.recorded)} with recordings`,
        23,
        NAVY,
        { bold: true }
      ),
      rectElement(
        1210,
        y + 51,
        322,
        60,
        18,
        bucket.links ? PALE_MINT : PALE_BLUE
      ),
      textElement(1371, y + 81, detail, 22, MID_BLUE, {
        bold: true,
        anchor: 'middle',
      })
    );
  });

  parts.push(
    textElement(
      800,
      1390,
      'An event is counted as recorded when it has at least one public recording link in METADATA.csv.',
      23,
      MID_BLUE,
      { anchor: 'middle' }
    ),
    textElement(
      800,
      1433,
      'Totals include event entries from 2017 through 2028. Recording links include playlists, videos, and archives.',
      23,
      MID_BLUE,
      { anchor: 'middle' }
    ),
    '</svg>'
  );

  return parts.join('\n');
}

async function renderImage(data, updated, outputPath = IMAGE) {
  const sharp = require('sharp');
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  await sharp(Buffer.from(buildSvg(data, updated), 'utf8'))
    .flatten({ background: OFF_WHITE })
    .removeAlpha()
    .png({ compressionLevel: 9 })
    .withMetadata({ density: 144 })
    .toFile(outputPath);
}

function parseCli(argv = process.argv.slice(2)) {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: false,
    options: {
      date: { type: 'string' },
      'no-image': { type: 'boolean', default: false },
      help: { type: 'boolean', short: 'h', default: false },
    },
  });

  if (values.date && !isValidIsoDate(values.date)) {
    throw new Error('--date must use YYYY-MM-DD');
  }

  return {
    date: values.date,
    noImage: values['no-image'],
    help: values.help,
  };
}

function usage() {
  return `Usage: node tools/generateRecordingsStats.js [options]

Options:
  --date YYYY-MM-DD  snapshot date shown on the page (default: today)
  --no-image         skip the PNG infographic
  -h, --help         show this help`;
}

async function main(argv = process.argv.slice(2)) {
  let args;
  try {
    args = parseCli(argv);
  } catch (error) {
    console.error(error.message);
    console.error(usage());
    process.exitCode = 1;
    return;
  }

  if (args.help) {
    console.log(usage());
    return;
  }

  const updated = args.date
    ? formatIsoSnapshotDate(args.date)
    : defaultSnapshotDate();

  let events;
  try {
    events = JSON.parse(fs.readFileSync(EVENTS, 'utf8'));
  } catch (error) {
    console.error(`Unable to read ${EVENTS}: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  const data = summarize(events);
  fs.mkdirSync(path.dirname(PAGE), { recursive: true });
  fs.writeFileSync(PAGE, markdown(data, updated), 'utf8');
  console.log(PAGE);

  if (!args.noImage) {
    try {
      await renderImage(data, updated);
      console.log(IMAGE);
    } catch (error) {
      if (error.code === 'MODULE_NOT_FOUND' && /sharp/.test(error.message)) {
        console.log(
          'sharp not installed; skipped the infographic (run npm install in tools)'
        );
      } else {
        throw error;
      }
    }
  }
}

if (require.main === module) {
  main().catch((error) => {
    console.error(error.message || String(error));
    process.exitCode = 1;
  });
}

module.exports = {
  EVENTS,
  IMAGE,
  PAGE,
  PERIODS,
  buildSvg,
  defaultSnapshotDate,
  formatIsoSnapshotDate,
  formatNumber,
  formatSnapshotDate,
  isPlaylist,
  isValidIsoDate,
  isYouTube,
  main,
  markdown,
  parseCli,
  percent,
  periodFor,
  renderImage,
  summarize,
  usage,
};
